# ============================================================
# settings.py | READS YOUR .env FILE. YOU DO NOT EDIT THIS FILE.
# ============================================================
#
# Everything you may want to change lives in TWO files:
#   .env          → which database, which model, keys, safety switches
#   knowledge.md  → what YOUR business words mean (makes answers accurate)
#
# This file only reads .env and fills in a safe default for anything
# you did not set. Every default here is the SAFE choice.
# ============================================================

import os
from pathlib import Path
from dotenv import load_dotenv, find_dotenv

# load_dotenv(find_dotenv()) → finds .env (in this folder or any parent folder)
#                              and loads every line in it as a setting
load_dotenv(find_dotenv())

# APP_FOLDER → the folder this file sits in, wherever you copy QueryDost
APP_FOLDER = Path(__file__).parent


# ------------------------------------------------------------
# Small helpers: read one setting from .env, with a default
# ------------------------------------------------------------
# os.getenv("NAME", default) → the value from .env, or the default if it is missing
def read_text(name, default):
    value = os.getenv(name, default)
    if value is None:
        return default
    return value.strip()


# "true", "yes", "1", "on" → True. Anything else → False
def read_true_false(name, default):
    value = read_text(name, str(default)).lower()
    return value in ["true", "yes", "1", "on"]


def read_number(name, default):
    return int(read_text(name, str(default)))


# "employees, leave_requests" → ["employees", "leave_requests"]
def read_list(name):
    value = read_text(name, "")
    items = []
    parts = value.split(",")
    for i in range(len(parts)):
        if parts[i].strip() != "":
            items.append(parts[i].strip())
    return items


# ------------------------------------------------------------
# A relative SQLite path like sqlite:///demo/hr_company.db should mean
# "next to QueryDost", not "wherever the terminal happens to be".
# ------------------------------------------------------------
def fix_sqlite_path(url):
    prefix = "sqlite:///"
    if not url.startswith(prefix):
        return url
    file_part = url[len(prefix):]
    if file_part == "" or Path(file_part).is_absolute():
        return url
    return prefix + (APP_FOLDER / file_part).resolve().as_posix()


# ============================================================
# 1. THE DATABASE
# ============================================================
# DATABASE_URL → one line that says which database, where, and which login.
#                The login should be a READ-ONLY user. See README.
DATABASE_URL = fix_sqlite_path(read_text("DATABASE_URL", "sqlite:///demo/hr_company.db"))

# SCHEMAS        → only look inside these schemas (blank = all user schemas)
# ALLOWED_TABLES → only these tables / views (blank = everything the login can see)
SCHEMAS = read_list("SCHEMAS")
ALLOWED_TABLES = read_list("ALLOWED_TABLES")


# ============================================================
# 2. THE MODEL
# ============================================================
# LLM_MODEL → "provider:model", e.g. "openai:gpt-6.1-sol", "azure_openai:my-deployment"
#             A strong model matters here: writing correct SQL on a messy schema is hard.
# LLM_TEMPERATURE → blank by default, because newer reasoning models reject it.
#                   Set 0 for older models (gpt-4o and similar) to get the same answer every time.
LLM_MODEL = read_text("LLM_MODEL", "openai:gpt-6.1-sol")
LLM_TEMPERATURE = read_text("LLM_TEMPERATURE", "")

# OPENAI_RESPONSES_API → true: use OpenAI's newer Responses API (needed for GPT-5 and later
#                        with tools). Set false only for very old setups.
OPENAI_RESPONSES_API = read_true_false("OPENAI_RESPONSES_API", True)


# ============================================================
# 3. HOW MUCH OF THE DATABASE THE MODEL SEES UP FRONT
# ============================================================
# SCHEMA_MODE
#   "full"   → every table, column and join goes into the prompt (best for small databases)
#   "lookup" → the model sees only table NAMES and looks up details when it needs them
#              (needed for big databases, keeps the prompt small)
#   "auto"   → "full" up to FULL_SCHEMA_MAX_TABLES tables, "lookup" above that
SCHEMA_MODE = read_text("SCHEMA_MODE", "auto").lower()
FULL_SCHEMA_MAX_TABLES = read_number("FULL_SCHEMA_MAX_TABLES", 15)

# SAMPLE_ROWS → example rows shown per table. Real values ('Pending', 'Pune')
#               help the model write correct WHERE clauses. 0 = show no data up front.
SAMPLE_ROWS = read_number("SAMPLE_ROWS", 3)


# ============================================================
# 4. GUARDRAILS
# ============================================================
# MAX_ROWS              → never send more than this many rows to the model
# QUERY_TIMEOUT_SECONDS → stop slow queries (PostgreSQL and MySQL)
# CHECK_SQL_IN_CODE     → Python parses every query and blocks anything that is not ONE SELECT
# HISTORY_MESSAGES      → how many past chat messages the model sees (keeps cost down)
MAX_ROWS = read_number("MAX_ROWS", 50)
QUERY_TIMEOUT_SECONDS = read_number("QUERY_TIMEOUT_SECONDS", 30)
CHECK_SQL_IN_CODE = read_true_false("CHECK_SQL_IN_CODE", True)
HISTORY_MESSAGES = read_number("HISTORY_MESSAGES", 12)
AUDIT_LOG_FILE = APP_FOLDER / "audit_log.txt"


# ============================================================
# 5. DATA CHANGES (OFF BY DEFAULT)
# ============================================================
# ALLOW_DB_CHANGES
#   false → the model can only read. It has no tool to change anything. (SAFE DEFAULT)
#   true  → the model can PROPOSE an INSERT / UPDATE. Nothing runs until a human
#           clicks Approve in the app. There is no switch to skip approval.
# APPROVER_DATABASE_URL → a SEPARATE login that may write, used only after Approve.
#                         For SQLite, leave it blank (the same file is opened in write mode).
ALLOW_DB_CHANGES = read_true_false("ALLOW_DB_CHANGES", False)
ALLOWED_CHANGE_TYPES = read_list("ALLOWED_CHANGE_TYPES")
if len(ALLOWED_CHANGE_TYPES) == 0:
    ALLOWED_CHANGE_TYPES = ["INSERT", "UPDATE"]
for i in range(len(ALLOWED_CHANGE_TYPES)):
    ALLOWED_CHANGE_TYPES[i] = ALLOWED_CHANGE_TYPES[i].upper()
APPROVER_DATABASE_URL = fix_sqlite_path(read_text("APPROVER_DATABASE_URL", ""))


# ============================================================
# 6. LOOK AND FEEL
# ============================================================
APP_TITLE = read_text("APP_TITLE", "QueryDost: talk to your database")
KNOWLEDGE_FILE = APP_FOLDER / read_text("KNOWLEDGE_FILE", "knowledge.md")
